import React, { useState, useEffect } from 'react'
import { useNavigate } from 'react-router-dom'
import { ChevronLeft, Sun, Moon, Monitor, Check } from 'lucide-react'

export default function Appearance() {
    const navigate = useNavigate()
    const [theme, setTheme] = useState(() => {
        return localStorage.getItem('theme') || 'system'
    })

    useEffect(() => {
        // Apply theme
        if (theme === 'dark') {
            document.documentElement.classList.add('dark')
            document.documentElement.classList.remove('light')
        } else if (theme === 'light') {
            document.documentElement.classList.add('light')
            document.documentElement.classList.remove('dark')
        } else {
            // System preference
            document.documentElement.classList.remove('dark', 'light')
            if (window.matchMedia('(prefers-color-scheme: dark)').matches) {
                document.documentElement.classList.add('dark')
            } else {
                document.documentElement.classList.add('light')
            }
        }
        localStorage.setItem('theme', theme)
    }, [theme])

    const themes = [
        {
            id: 'light',
            icon: Sun,
            label: 'Light',
            description: 'Use light theme'
        },
        {
            id: 'dark',
            icon: Moon,
            label: 'Dark',
            description: 'Use dark theme'
        },
        {
            id: 'system',
            icon: Monitor,
            label: 'System',
            description: 'Follow system preference'
        }
    ]

    return (
        <div className="min-h-screen bg-gray-50 px-4 py-6 pb-20">
            <div className="flex items-center gap-3 mb-6">
                <button 
                    onClick={() => navigate(-1)}
                    className="p-2 hover:bg-gray-200 rounded-lg transition"
                >
                    <ChevronLeft size={24} className="text-gray-700" />
                </button>
                <h1 className="text-2xl font-bold text-gray-800">Appearance</h1>
            </div>

            <div className="bg-white rounded-xl shadow-sm border border-gray-100 overflow-hidden">
                <div className="p-4 border-b border-gray-100">
                    <p className="text-sm text-gray-500">Choose how the app looks</p>
                </div>
                {themes.map((option) => {
                    const Icon = option.icon
                    const isSelected = theme === option.id
                    return (
                        <button
                            key={option.id}
                            onClick={() => setTheme(option.id)}
                            className={`w-full flex items-center justify-between px-4 py-4 hover:bg-gray-50 transition border-b border-gray-100 last:border-0 ${
                                isSelected ? 'bg-gray-50' : ''
                            }`}
                        >
                            <div className="flex items-center gap-3">
                                <div className={`p-2 rounded-lg ${
                                    isSelected ? 'bg-gray-800 text-white' : 'bg-gray-100 text-gray-600'
                                }`}>
                                    <Icon size={20} />
                                </div>
                                <div className="text-left">
                                    <span className="font-medium text-gray-800">{option.label}</span>
                                    <p className="text-xs text-gray-400">{option.description}</p>
                                </div>
                            </div>
                            {isSelected && (
                                <Check size={20} className="text-gray-800" />
                            )}
                        </button>
                    )
                })}
            </div>

            <div className="mt-6 bg-blue-50 rounded-xl p-4 border border-blue-200">
                <p className="text-sm text-blue-700">
                    💡 Changes will apply instantly. Your preference is saved locally.
                </p>
            </div>
        </div>
    )
}
